const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define country geometries
  const namibia = ee.Geometry.Rectangle([11.7, -28.97, 25.26, -16.96]);
  const botswana = ee.Geometry.Rectangle([19.99, -26.87, 29.62, -17.79]);
  const lesotho = ee.Geometry.Rectangle([27.0, -30.67, 29.45, -28.6]);

  const countries = {
    'Namibia': namibia,
    'Botswana': botswana,
    'Lesotho': lesotho
  };

  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Calculate rainfall for Dec 2018 - Jan 2019
  const rainfall_2018_19 = chirps
    .filterDate('2018-12-01', '2019-02-01')
    .sum();

  // Calculate climatology: all Dec-Jan periods from 2000-2019
  let climatology_2018_19 = ee.Image(0);
  let count_years = 0;

  for (let year = 2000; year < 2019; year++) {
    const dec_jan = chirps.filterDate(year + '-12-01', (year + 1) + '-02-01').sum();
    climatology_2018_19 = climatology_2018_19.add(dec_jan);
    count_years++;
  }
  climatology_2018_19 = climatology_2018_19.divide(ee.Image(count_years));

  print('Years in climatology:', count_years);

  let all_below = true;

  for (const [country, geom] of Object.entries(countries)) {
    // Get rainfall for 2018-19
    const val_2018_19 = rainfall_2018_19.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: 5000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    // Get climatological average
    const val_clim = climatology_2018_19.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: 5000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    // Check for data validity
    if (val_2018_19 === null || val_clim === null || isNaN(val_2018_19) || isNaN(val_clim)) {
      print(country + ' data invalid');
      print('<answer>C3</answer>');
      return;
    }

    const below = val_2018_19 < val_clim;
    print(country + ': 2018-19=' + val_2018_19.toFixed(1) + 'mm, Clim=' + val_clim.toFixed(1) + 'mm, Below=' + below);

    if (!below) {
      all_below = false;
    }
  }

  print('---');
  if (all_below) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
